def _build_component_06():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        choices = []
        for name in names:
            rows = packages[name]
            choices.append([None] + rows)

        def valid(assignment):
            selected = {name: row for name, row in zip(names, assignment)
                        if row is not None}
            for name, bounds in roots.items():
                if name not in selected or not bounds[0] <= selected[name]["version"] <= bounds[1]:
                    return False
            for name, row in selected.items():
                version = row["version"]
                if version in blocked.get(name, []) or (name in pins and version != pins[name]):
                    return False

            edges = {name: [] for name in selected}
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    if other not in selected:
                        return False
                    ov = selected[other]["version"]
                    if not dep["min"] <= ov <= dep["max"]:
                        return False
                    edges[name].append(other)

            # Only the dependency closure of the roots is installed.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                if name not in edges:
                    return False
                stack.extend(edges[name])
            if reachable != set(selected):
                return False

            visiting, visited = set(), set()
            def acyclic(name):
                if name in visiting:
                    return False
                if name in visited:
                    return True
                visiting.add(name)
                if any(not acyclic(other) for other in edges[name]):
                    return False
                visiting.remove(name)
                visited.add(name)
                return True
            return all(acyclic(name) for name in edges)

        best = None
        best_vector = None
        for assignment in product(*choices):
            if not valid(assignment):
                continue
            vector = tuple(-1 if row is None else row["version"] for row in assignment)
            if best_vector is None or vector < best_vector:
                best_vector, best = vector, assignment
        if best is None:
            return {"error": "unsatisfiable"}
        return {"versions": {name: row["version"] for name, row in zip(names, best)
                              if row is not None}}

    return solve


def _build_component_07():
    from itertools import combinations

    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["start"] < ordered[i - 1]["end"]
                   for i in range(1, len(ordered))):
                continue
            selected = sorted(ids)
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}

    return solve


def _build_component_08():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bits = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source, target = data["source"], data["target"]
        initial_mask = bits.get(source, 0)
        start = data["start"]
        coupons = data["coupons"]
        initial = (source, initial_mask, coupons)
        dist = {initial: start}
        queue = [(start, source, initial_mask, coupons)]

        while queue:
            time, node, mask, left = heapq.heappop(queue)
            state = (node, mask, left)
            if dist.get(state) != time:
                continue
            if node == target and mask == full and left == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], left)]
                if left:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, left - 1))
                for duration, next_left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bits.get(nxt, 0)
                    next_state = (nxt, next_mask, next_left)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_mask, next_left))
        return {"arrival": None}

    return solve


